  if (error is! MobileApiException) {
    return error.toString();
  }
  return switch (error.code) {
    'batch_context_conflict' =>
      'Batch boshqa joyda o‘zgargan. Eski mahsulot chop etilmadi; holatni yangilang.',
    'batch_store_failed' =>
      'Server batch holatini saqlay olmadi. Amal bekor qilindi; qayta urinishdan oldin holatni yangilang.',
    'batch_not_active' =>
      'Faol batch topilmadi. Holatni yangilab, yangi batch boshlang.',
    'submit_failed' ||
    'store_write_failed' =>
      'ERPNext operatsiyani qabul qilmadi va batch xavfsizlik uchun to‘xtatildi: ${error.message}',
    'print_failed' => 'Printer chop etmadi: ${error.message}',
    _ => error.message,
  };
}

String formatCompactKg(double value) {
  var text = value.toStringAsFixed(3);
  while (text.contains('.') && text.endsWith('0')) {
    text = text.substring(0, text.length - 1);
  }
  if (text.endsWith('.')) {
    text = text.substring(0, text.length - 1);
  }
  return text;
}

String buildPrintSuccessMessage(
  GScaleMaterialReceiptPrintResponse response, {
  String serverLabel = '',
}) {
  final qty = formatCompactKg(
    response.netQty > 0 ? response.netQty : response.qty,
  );
  final status = response.status.trim().toLowerCase();
  final target = serverLabel.trim();
  final targetText = target.isEmpty ? '' : ' • $target';
  final duplicateText =
      response.printCount > 1 ? ' • ${response.printCount} ta' : '';
  if (status == 'printed') {
    return 'Printerga yuborildi$targetText$duplicateText • netto $qty ${response.unit}';
  }
  final draft = response.draftName.isEmpty ? 'draft' : response.draftName;
  return '$draft submit qilindi$targetText$duplicateText • netto $qty ${response.unit}';
}

